import { auth } from '@/lib/auth-options';
import { redirect } from 'next/navigation';

export default async function DashboardPage() {
  const session = await auth();

  if (!session?.user) {
    redirect('/login');
  }

  switch (session.user.role) {
    case 'ADMIN':
      redirect('/admin');
    case 'REPORTER':
      redirect('/reporter');
    case 'SCOPIST':
      redirect('/scopist');
    default:
      redirect('/jobs');
  }
}
